/**
 * Input — generated by the React Native Reusables CLI (`input`), re-skinned.
 *
 * Deviations from upstream:
 * - A field is a well cut into the surface, never an object on it: `card` fill, a
 *   real `input` (border-control) edge, and the `insetField` recess drawn with
 *   React Native `boxShadow` through `useFieldRecess`. Upstream's
 *   `shadow-sm shadow-black/5` lifts it, which is the button's gesture.
 * - 48 tall (the touch minimum) with `font-sans text-base`; the `sm:h-9` desktop
 *   step and every `dark:` variant are removed.
 * - The native placeholder is `muted-foreground` at full strength: `/50` would
 *   composite under the contrast floor the token was measured for.
 * - `invalid` paints the edge `destructive` on native, where upstream's
 *   `aria-invalid:` variant only reaches web.
 * - React 19 idioms: `use` and `<Context value>`, and no extra `RefAttributes` —
 *   `ComponentProps` already carries `ref`, and upstream's second ref type made
 *   every `useRef` passed as `ref` a type error.
 */
import { cn } from '@/lib/utils';
import { useFieldRecess } from '@/ui/elevation';
import { Platform, TextInput } from 'react-native';

function Input({
  className,
  style,
  invalid = false,
  ...props
}: React.ComponentProps<typeof TextInput> & {
  /** The value was refused; draws the edge in `destructive`. */
  invalid?: boolean;
}) {
  const recess = useFieldRecess();
  return (
    <TextInput
      className={cn(
        'flex h-12 w-full min-w-0 flex-row items-center rounded-md border border-input bg-card px-4 font-sans text-base text-foreground placeholder:text-muted-foreground',
        invalid && 'border-destructive',
        props.editable === false &&
          cn(
            'opacity-50',
            Platform.select({ web: 'disabled:pointer-events-none disabled:cursor-not-allowed' }),
          ),
        Platform.select({
          web: 'outline-none focus-visible:ring-2 focus-visible:ring-ring selection:bg-primary selection:text-primary-foreground',
        }),
        className,
      )}
      style={[recess, style]}
      {...props}
    />
  );
}

export { Input };
